function solveHyperbolic(Mh,e){
  let H=Math.asinh(Mh/e);
  console.log('init',H);
  for(let i=0;i<40;i++){
    const sh=Math.sinh(H), ch=Math.cosh(H);
    const f=e*sh - H - Mh;
    const fp=e*ch -1;
    const d=f/fp;
    console.log(i,H,sh,ch,f,fp,d);
    H-=d;
    if(Math.abs(d)<1e-10) break;
    if(!isFinite(H)) break;
  }
  return H;
}
console.log(solveHyperbolic(13480,1.000001));

function posTest(){
  const c={e:1, a:null, q:0.43, i:71, om:330, w:261, tp:1667909.5, per:null, n:null, epoch:1667909.5};
  const jd=2451545;
  let a = c.a;
  if(!isFinite(a) || a>0) { const q=c.q; if(isFinite(q) && c.e!==1) a=q/(1-c.e); else a=-1; }
  console.log('a',a);
  const dt=jd-c.tp;
  const negA=-a;
  const K=0.01720209895, MU=K*K;
  const n_h=Math.sqrt(MU/(negA*negA*negA));
  const Mh=n_h*dt;
  console.log('Mh',Mh);
  const ee=1.000001;
  const H=solveHyperbolic(Mh, ee);
  console.log('H',H);
  const ch=Math.cosh(H), sh=Math.sinh(H);
  console.log('ch',ch,'sh',sh);
  const denom=1-ee*ch;
  console.log('denom',denom);
  const cosNu=(ch-ee)/denom, sinNu=Math.sqrt(ee*ee-1)*sh/denom;
  console.log('cosNu',cosNu,'sinNu',sinNu);
  const r=a*(1-ee*ch);
  console.log('r',r);
  const xpf=r*cosNu, ypf=r*sinNu;
  console.log('xpf',xpf,'ypf',ypf);
}
posTest();
